# -*- coding: utf-8 -*-
# Pack TA: ¿quién más atribuye a Ibn Abbas que el tahrif es de significado (taʾwil) y no de texto? (el taʿliq de al-Bujari)
S = "https://shamela.ws/book/"
QT = "quran-tafsir.net (texto en línea del comentario; sin paginación impresa)"
KSU = "quran.ksu.edu.sa (Proyecto Ayat, Universidad Rey Saud; sin paginación impresa)"
USO = "Pack «Ibn Abbas y el tahrif» (ampliación) · quién más lo atribuye a Ibn Abbas"
TACARDS = [
 # ---------- B. Atribución explícita a Ibn Abbas ----------
 dict(id="TA01", key="Hay", tag="745 H · Abu Hayyan al-Andalusi", specs=["TA-hy275"],
  title="Abu Hayyan: «y se dijo: por interpretación, conservándose el texto de la Torá; lo dijo Ibn Abbas»",
  ref="Abu Hayyan al-Andalusi, al-Bahr al-Muhit, sobre el Corán 2:75 («luego lo tergiversaban»)",
  ar_ref="البحر المحيط، تفسير ٢:٧٥", site=QT, url="https://quran-tafsir.net/hayyan/sura2-aya75.html",
  es=["[…] Y la palabra de Dios que tergiversaron: se dijo que es la Torá, [[a:que la tergiversaron cambiando palabras por su cuenta, y es la opinión de la mayoría]]. Y [[k:se dijo: [fue] por interpretación, quedando el texto de la Torá; lo dijo Ibn Abbas]]. Y se dijo: es la palabra de Dios que oyeron en el Sinaí. Y se dijo: lo que oían de la revelación que descendía sobre el Mensajero de Dios…"],
  prueba="Abu Hayyan (m. 745 H), uno de los grandes gramáticos y exegetas de al-Andalus, recoge sin discutirla la atribución a Ibn Abbas: la tergiversación fue «por interpretación, quedando el texto de la Torá». Es una atribución explícita a Ibn Abbas, hecha en el comentario de 2:75 y distinta de las de Ibn Atiyya (H02a/H15) e Ibn Jaldun (H20a).",
  ojo="Abu Hayyan pone esa lectura en segundo lugar («y se dijo») y da primero la de la mayoría: cambio de palabras. No elige. En 5:41, según mi agente (OCR), recoge de Ibn Abbas otra cosa: que lo cambiado son «los límites [hudud] de Dios en la Torá». Es el texto de una web, no de la edición impresa; sin página.", uso=USO),

 dict(id="TA02", key="IK", tag="774 H · Ibn Kathir", specs=["TA-ik378"],
  title="Ibn Kathir: «así transmitió al-Bujari de Ibn Abbas… nadie quita una palabra de un libro de Dios, pero lo tergiversan interpretándolo mal»; y luego lo matiza",
  ref="Ibn Kathir, Tafsir al-Qurʾan al-ʿAzim, sobre el Corán 3:78 («tuercen sus lenguas con el Libro»)",
  ar_ref="تفسير ابن كثير، آل عمران ٧٨", site=KSU, url="https://quran.ksu.edu.sa/tafseer/katheer/sura3-aya78.html",
  es=["Y dijeron Mujahid, al-Shaʿbi, al-Hasan, Qatada y al-Rabiʿ ibn Anas: «tuercen sus lenguas con el Libro»: lo tergiversan. [[k:Y así transmitió al-Bujari de Ibn Abbas: que tergiversan y «yazidun» [texto impreso; en al-Bujari: «yuzilun», quitan]; y nadie de la creación de Dios quita una palabra de un libro de Dios, pero lo tergiversan: lo interpretan en un sentido que no es el suyo]]. Y dijo Wahb ibn Munabbih: [[k:«La Torá y el Evangelio, como Dios los reveló, no han cambiado ni una letra; pero extravían con la tergiversación y la interpretación]], y con libros que escribían de su cuenta [«y dicen: esto es de Dios, y no es de Dios»]; y en cuanto a los libros de Dios, están protegidos y no se alteran»; lo transmitió Ibn Abi Hatim. [[a:Y si Wahb se refiere a lo que tienen en sus manos, no hay duda de que le han entrado el cambio, la tergiversación, la adición y la omisión; y en cuanto a la traducción al árabe que se ve, tiene gran error, muchas adiciones y omisiones…]] Pero si se refiere a los libros de Dios, los que Él mismo escribió, esos, como dijo, están protegidos: no les entró nada."],
  prueba="Ibn Kathir (m. 774 H) cita expresamente el taʿliq: «así transmitió al-Bujari de Ibn Abbas» que nadie quita una palabra de un libro de Dios, pero lo tergiversan interpretándolo en otro sentido. Y lo junta con la de Wahb ibn Munabbih. Es otro sabio de primer orden que lo atribuye a Ibn Abbas.",
  ojo="No lo hace suyo: justo después dice que, si Wahb habla de lo que ahora tienen en las manos, «no hay duda de que le entró el cambio» (azul, H18); solo acepta la protección de «los libros de Dios que Él mismo escribió». Y en 2:79 cita de Ibn Abbas el relato contrario (TA10). Detalle del texto: esta edición en línea imprime «يزيدون» («añaden»), no «يزيلون» («quitan») como al-Bujari y al-Qasimi cuando lo copia (TA05); parece errata.", uso=USO),

 dict(id="TA03", key="Alu", tag="1270 H · al-Alusi", specs=["TA-al275"],
  title="al-Alusi: «lo interpretan con una interpretación corrupta, y a eso se inclinó Ibn Abbas; y la mayoría sostiene el cambio de palabras»",
  ref="al-Alusi, Ruh al-maʿani, sobre el Corán 2:75",
  ar_ref="روح المعاني، البقرة ٧٥", site=QT, url="https://quran-tafsir.net/alusy/sura2-aya75.html",
  es=["«{Y había un grupo de ellos que oía la palabra de Dios y luego la tergiversaba}»: es decir, un grupo de sus antepasados, los rabinos: oyen la Torá y [[k:la interpretan con una interpretación corrupta según sus propósitos; y a eso se inclinó Ibn Abbas —Dios esté complacido con ambos—]], [[a:y la mayoría sostiene que su tergiversación fue por cambiar palabras por su cuenta]], como hicieron con su descripción [de Muhammad]: se transmite que entre sus rasgos en ella estaba «blanco, de estatura media» y lo cambiaron por «moreno, alto», y cambiaron el versículo de la lapidación por el ennegrecimiento del rostro, como figura en al-Bujari. Y se dijo: [lo que oyeron fue] lo que escucharon en el Sinaí…"],
  prueba="al-Alusi (m. 1270 H), muftí de Bagdad y autor de uno de los grandes comentarios del Corán, dice en 2:75 que Ibn Abbas se inclinó por la interpretación corrupta (taʾwil) y pone enfrente que «la mayoría» sostiene el cambio de palabras. Otro testimonio explícito, esta vez del siglo XIX.",
  ojo="al-Alusi no adopta la de Ibn Abbas: la presenta como la minoría. Y en su comentario de 4:46 (TA12) recoge de Ibn Abbas, vía al-Bujari, el relato de que «cambiaron el Libro de Dios y escribieron con sus manos». O sea, para al-Alusi Ibn Abbas aparece en las dos posturas. Texto en línea, sin paginación impresa.", uso=USO),

 dict(id="TA04", key="IAs", tag="1393 H · Ibn ʿAshur", specs=["TA-ia446", "TA-ia513"],
  title="Ibn ʿAshur: «lo que se transmite de Ibn Abbas, que el tahrif es corrupción de la interpretación, y que un pueblo no se propone cambiar su libro, se refiere a la mayoría de sus casos»",
  ref="Ibn ʿAshur, al-Tahrir wa-l-tanwir, sobre el Corán 4:46 y 5:13",
  ar_ref="التحرير والتنوير، النساء ٤٦ والمائدة ١٣", site=QT, url="https://quran-tafsir.net/ashour/sura4-aya46.html · https://quran-tafsir.net/ashour/sura5-aya13.html",
  es=["[…] Y cabe que «tahrif» derive de «harf», que es la palabra y la escritura, y entonces se refiere a cambiar las palabras de la Torá y sustituirlas por otras para acomodarlas a los caprichos de la gente de las pasiones… [[a:Y lo evidente es que los judíos cometieron las dos cosas en su libro.]] [[k:Y lo que se transmite de Ibn Abbas, que la tergiversación es corrupción de la interpretación y que un pueblo no se propone cambiar su libro,]] [[a:se refiere a la mayor parte de sus casos]]. Según la primera posibilidad el uso de «ʿan» (de) en «ʿan mawadiʿihi» es figurado; y según la segunda es literal, pues el tahrif es entonces traslado y remoción.",
      "[…] Y esta tergiversación es sobre todo por mala interpretación, siguiendo el capricho, y por ocultar muchas normas para complacer a la gente común; [[a:se dijo: y [también] por cambiar las palabras de sus libros]]. [[k:Y de Ibn Abbas: lo que indica que la tergiversación es corrupción de la interpretación.]] Ya se habló de ello al comentar «de los que se hicieron judíos tergiversan las palabras de su lugar», en sura al-Nisaʾ (46)."],
  prueba="Ibn ʿAshur (m. 1393 H), el gran exegeta tunecino del siglo XX, recoge en dos pasajes lo que «se transmite de Ibn Abbas»: que la tergiversación es corrupción de la interpretación, «y que un pueblo no se propone cambiar su libro». Es la misma idea y casi las mismas palabras del taʿliq de al-Bujari.",
  ojo="Lo recoge pero lo limita: dice que se refiere a «la mayoría de sus casos» y que «lo evidente es que los judíos cometieron las dos cosas»; en 5:13 añade «se dijo: y también cambiando las palabras». No da cadena. Texto en línea sin paginación impresa.", uso=USO),

 dict(id="TA05", key="Qas", tag="1332 H · al-Qasimi (citando a Ibn Kathir)", specs=["TA-qs378"], secondary=True,
  title="al-Qasimi copia a Ibn Kathir: «y así transmitió al-Bujari de Ibn Abbas: tergiversan: quitan; y nadie quita una palabra… pero lo interpretan en un sentido que no es el suyo»",
  ref="al-Qasimi, Mahasin al-taʾwil, sobre el Corán 3:78 (citando a Ibn Kathir)",
  ar_ref="محاسن التأويل، آل عمران ٧٨", site=QT, url="https://quran-tafsir.net/qasimi/sura3-aya78.html",
  es=["Dijo el imán Ibn Kathir: […] Y dijeron Mujahid, al-Shaʿbi, al-Hasan, Qatada y al-Rabiʿ ibn Anas: «tuercen sus lenguas con el Libro»: lo tergiversan. [[k:Y así transmitió al-Bujari de Ibn Abbas: «que tergiversan: quitan. Y nadie quita una palabra de un libro de Dios —Poderoso y Majestuoso—, pero lo tergiversan: lo interpretan en un sentido que no es el suyo»]]…"],
  prueba="al-Qasimi (m. 1332 H, Damasco) reproduce entero el pasaje de Ibn Kathir con la atribución a Ibn Abbas. Su texto trae «يزيلون» («quitan»), la palabra del taʿliq. Que lo cite un reformista moderno (Sirry lo toma como ejemplo de cómo defiende la fiabilidad de la Torá: TA09) muestra que la atribución llegó viva al siglo XX.",
  ojo="Es una cita de segunda mano: al-Qasimi copia a Ibn Kathir (TA02). Su propio juicio sobre el tahrif está en 2:75 (TA13): no niega que hubiera cambio de texto.", uso=USO),

 # ---------- C. La misma idea, atribuida a al-Bujari o leída desde Ibn Abbas ----------
 dict(id="TA06", key="IQ", tag="751 H · Ibn al-Qayyim (y al-Qasimi, que lo cita)", specs=["TA-ig", "TA-qs446"],
  title="Ibn al-Qayyim: «un grupo de los imanes del hadiz, el fiqh y el kalam dijo: el cambio fue en la interpretación, no en el texto: es la doctrina de al-Bujari y la elección de al-Razi»",
  ref="Ibn al-Qayyim, Ighathat al-lahfan min masayid al-shaytan, capítulo 13 (Wikisource, cap. 34); y al-Qasimi, Mahasin al-taʾwil, sobre el Corán 4:46, que lo copia",
  ar_ref="إغاثة اللهفان، الباب الثالث عشر", site="ar.wikisource.org (texto) y quran-tafsir.net", url="https://ar.wikisource.org/wiki/إغاثة_اللهفان/الباب_الثالث_عشر/34 · https://quran-tafsir.net/qasimi/sura4-aya46.html",
  es=["Capítulo. Las opiniones de la gente sobre la Torá que tienen en sus manos han diferido: ¿está cambiada o el cambio y la tergiversación se dio en la interpretación y no en lo revelado? [Hay] tres opiniones: dos extremos y un punto medio. [[a:Un grupo se excedió y afirmó que toda ella o la mayor parte está cambiada y alterada]], no es la Torá que Dios reveló a Moisés… Y los enfrentó otro grupo de los imanes del hadiz, del fiqh y del kalam, que dijeron: [[k:el cambio se dio en la interpretación, no en lo revelado]]. [[k:Y esta es la doctrina de Abu ʿAbd Allah Muhammad ibn Ismaʿil al-Bujari, que dijo en su Sahih: «yuharrifun: yuzilun [quitan]; y nadie quita una palabra de un libro de Dios, pero lo tergiversan: lo interpretan en un sentido que no es el suyo»]]. [[k:Y esta es la elección de al-Razi en su tafsir.]]",
      "Y dijo el imán Ibn al-Qayyim en «Ighathat al-lahfan»: […] [[k:Y dijo un grupo de los imanes del hadiz, el fiqh y el kalam: el cambio solo ocurrió en la interpretación. Dijo al-Bujari en su Sahih: «yuharrifun: yuzilun [quitan]; y nadie quita una palabra de un libro de Dios; pero lo interpretan en un sentido que no es el suyo»]]. [[k:Y es también la opción de al-Razi.]] [[a:Dijo un grupo: toda o la mayoría está cambiada]]…"],
  prueba="Ibn al-Qayyim (m. 751 H) atribuye la doctrina «el cambio fue solo de interpretación» a «imanes del hadiz, el fiqh y el kalam»; la ancla en al-Bujari (con el taʿliq literal) y en al-Razi, y no la tacha de falsa. Al-Qasimi copia el pasaje, con lo que esa cadena de citas llega al siglo XX.",
  ojo="Aquí la atribución es a al-Bujari («dijo en su Sahih»), no a Ibn Abbas: es un testimonio de la existencia de la lectura, no del nombre. Y Ibn al-Qayyim no la adopta: presenta tres posturas y, según el texto que sigue (fuera de la captura), una tercera intermedia —se añadió algo y se cambiaron pocas cosas— es la que eligió «nuestro maestro» Ibn Taymiyya en al-Yawab al-sahih.", uso=USO),

 dict(id="TA07", key="Raj", tag="Siglo XXI · Abd al-ʿAziz al-Rayihi (comentario oral)", specs=["TA-rj647"], secondary=True,
  title="al-Rayihi: Bujari comenta a Ibn Abbas y «explica su dicho como tahrif del significado, no de la palabra»; y se pregunta: «¿cómo dice eso, si vemos que quitaron muchas palabras?»",
  ref="Abd al-ʿAziz al-Rayihi, Sharh Kitab al-Tawhid min Sahih al-Bujari, lección 647 (en su sitio web)",
  ar_ref="شرح كتاب التوحيد من صحيح البخاري، الدرس ٦٤٧", site="shrajhi.com.sa (transcripción de la lección)", url="https://shrajhi.com.sa/lessons/647",
  es=["[…] «Y dijo Ibn Abbas: […] {Tergiversan} = quitan» […] [[k:Y al-Bujari —Dios tenga misericordia de él— comentó las palabras de Ibn Abbas, que Dios esté complacido con ambos, y dijo:]] «Y nadie quita una palabra de un libro de Dios —Poderoso y Majestuoso—, pero lo tergiversan: lo interpretan en un sentido que no es el suyo». [[k:Así explicó el dicho de Ibn Abbas como tahrif del significado, no tahrif de la palabra]], como [quien dice] «se estableció sobre el trono» y [lo cambian por] «se apoderó»: no puede borrarlas del Corán ni quitarlas, pero quita el significado y lo tergiversa.",
      "Y los libros de Dios son la Torá, el Evangelio, el Salterio y el Corán; y es sabido que la Torá y el Evangelio fueron tergiversados, cambiados y alterados […] ¿Cómo, pues, dice al-Bujari «nadie puede quitar una palabra de un libro de Dios», [[a:cuando vemos que quitaron muchas palabras de la Torá y el Evangelio?]] […] Si se dice: la Torá que tienen en las manos es la que fue tergiversada y cambiada, pero la que está junto a Dios nadie puede tocarla: decimos: eso no tiene problema; y el problema está en la Torá que fue revelada y el Evangelio que fue revelado: [[a:lo que escribieron con sus manos y atribuyeron a Dios; pero lo que Dios reveló no pudieron tergiversar su palabra]]."],
  prueba="Un erudito contemporáneo (el šayj al-Rayihi, que comenta Kitab al-Tawhid de al-Bujari) lee el taʿliq como «tahrif del significado, no de la palabra» y lo explica con el ejemplo de «se estableció» → «se apoderó». Es decir: en la tradición de comentario actual, esa es la lectura natural del taʿliq.",
  ojo="Él mismo lo discute: señala que la frase de al-Bujari «tiene un problema» porque «vemos que quitaron muchas palabras de la Torá y el Evangelio» y lo resuelve distinguiendo la Torá revelada (cuyo texto nadie puede tocar) de los ejemplares escritos por los judíos (alterados). Lo lee como comentario de al-Bujari sobre Ibn Abbas, no como palabras de Ibn Abbas. Es transcripción de una lección, no un libro.", uso=USO),

 dict(id="TA08", key="Tab", tag="310 H · al-Tabari", specs=["TA-tb275"],
  title="al-Tabari, 2:75: «luego lo tergiversan» = «luego cambian su significado y su interpretación»; pero antes dice que es más probable que cambiaran lo que hay en sus libros sobre la descripción de Muhammad",
  ref="al-Tabari, Yamiʿ al-bayan, sobre el Corán 2:75, vol. 2, p. 248 y siguientes (el texto en línea trae los marcadores impresos «2-248»)",
  ar_ref="تفسير الطبري، البقرة ٧٥", site=KSU, url="https://quran.ksu.edu.sa/tafseer/tabary/sura2-aya75.html",
  es=["[…] y [es] más cercano a que tergiversen lo que hay en sus libros, [[a:de la descripción de vuestro Profeta Muhammad —la paz sea con él— y su rasgo, y lo cambien]], conscientes de ello, [y] lo nieguen y mientan […]",
      "Y quiere decir con su dicho «luego lo tergiversan»: [[k:luego cambian su significado y su interpretación y lo alteran]]. Y su origen es «desviar una cosa de su lado», que es inclinarla hacia otro. Así, su dicho «lo tergiversan» es [[k:que lo inclinan de su aspecto y su significado, que es [el suyo], hacia otro]]. Y Dios informó de que hicieron lo que hicieron con conocimiento de la interpretación de lo que tergiversaron…"],
  prueba="El primer gran comentarista (m. 310 H), cuando explica el verbo, lo glosa por el significado: «cambian su significado y su interpretación», «lo inclinan de su sentido hacia otro». Es una glosa semántica de «tahrif» que apunta al sentido.",
  ojo="Tabari no es un apoyo limpio: en el párrafo anterior dice que es «más cercano a que tergiversen lo que hay en sus libros de la descripción de vuestro Profeta y lo cambien» (azul), es decir, también cambio en los libros. No atribuye nada a Ibn Abbas aquí: en 2:75 no tiene ninguna narración de Ibn Abbas (Y7). Sirry lo menciona en la misma línea (TA09).", uso=USO),

 dict(id="TA09", key="Sir", tag="2014 · Mun'im Sirry (Oxford UP)", specs=["TA-sirry"], secondary=True, lang="inglés (página del libro en línea)",
  title="Sirry: Qasimi encuentra apoyo «incluso en al-Bujari, que narra la explicación de Ibn Abbas del significado de tahrif: falsificación en términos de interpretación»",
  ref="Mun'im Sirry, Scriptural Polemics: The Qur'an and Other Religions (Oxford University Press, 2014), cap. 1, p. 14 (y nota 25: Qasimi, Mahasin al-taʾwil, vol. 1, p. 49)",
  ar_ref="Sirry 2014, p. 14", site="ebin.pub (copia del libro; la paginación es la impresa)", url="https://ebin.pub/scriptural-polemics-the-quran-and-other-religions-0199359377-9780199359370.html",
  trnote="Traducción propia del inglés. ",
  es=["[…] para demostrar la fiabilidad de la Torá. Curiosamente, [Qasimi] encuentra apoyo a su postura incluso en los eruditos más tradicionalistas, como [[k:el muhaddith al-Bujari (m. 256/870), que narra la explicación de Ibn Abbas del significado de tahrif, es decir, la falsificación en términos de interpretación]]."],
  prueba="Un académico de Oxford (Sirry) escribe, sin reservas, que al-Bujari «narra la explicación de Ibn Abbas del significado de tahrif: falsificación en términos de interpretación», y que al-Qasimi la usa para defender la fiabilidad de la Torá. Es un testimonio académico moderno de que la atribución a Ibn Abbas circula así.",
  ojo="Es una paráfrasis de Sirry de lo que dice al-Qasimi (nota 25 remite a la introducción de su tafsir, vol. 1, p. 49: esa página no la he podido leer), no un texto de al-Bujari. Sirry no valora la autenticidad. Lo que sí he comprobado yo es el pasaje de al-Qasimi en 3:78 y 4:46 (TA05, TA06).", uso=USO),

 # ---------- D. Lo que hay que decir en contra ----------
 dict(id="TA10", key="IK2", tag="774 H · Ibn Kathir (mismo autor, otro versículo)", specs=["TA-ik279"],
  title="Ibn Kathir, 2:79: de Ibn Abbas, vía al-Zuhri: «Dios os ha dicho que la gente del Libro cambió el Libro de Dios y lo alteró, y escribieron con sus manos el Libro»",
  ref="Ibn Kathir, Tafsir al-Qurʾan al-ʿAzim, sobre el Corán 2:79 (relato de Ibn Abbas, también en al-Bujari)",
  ar_ref="تفسير ابن كثير، البقرة ٧٩", site=KSU, url="https://quran.ksu.edu.sa/tafseer/katheer/sura2-aya79.html",
  es=["Y dijo al-Zuhri: me informó ʿUbayd Allah ibn ʿAbd Allah, [[k:de Ibn Abbas, que dijo]]: «¡Musulmanes! ¿Cómo preguntáis a la gente del Libro por algo cuando vuestro Libro, que Dios reveló a Su Profeta, es lo más reciente de las noticias de Dios, que leéis puro, sin mezcla? Y Dios os ha dicho que [[k:la gente del Libro cambió el Libro de Dios y lo alteró, y escribieron con sus manos el Libro]], y dijeron: ‹esto viene de Dios›, para comprar con ello un precio vil»."],
  prueba="El mismo Ibn Kathir que cita el taʿliq en 3:78 (TA02) cita en 2:79, de Ibn Abbas, el relato que dice lo contrario: que «cambiaron el Libro de Dios y lo alteraron y escribieron con sus manos el Libro». Es el pasaje que al-Bujari también recoge (7363) y el más usado contra la lectura «solo interpretación».",
  ojo="Hay que presentarlo: si se cita a Ibn Abbas a favor de «solo interpretación», se cita también a Ibn Abbas en contra. Ibn Hajar mismo señala que el taʿliq «contradice» otra narración de Ibn Abbas en un capítulo anterior (Fath 13/533). Según mi agente Y7, la cláusula «cambiaron» está en la versión de ʿUbayd Allah (7523) y no en la de ʿIkrima (7522); no lo he comprobado yo.", uso=USO),

 dict(id="TA11", key="Tab2", tag="310 H · al-Tabari (narraciones de Ibn Abbas)", specs=["TA-tb378", "TA-tb279"],
  title="Las narraciones de Ibn Abbas en al-Tabari van en otra dirección: «añadían al libro de Dios lo que Dios no reveló» (3:78) y «escribieron un libro con sus manos» (2:79)",
  ref="al-Tabari, Yamiʿ al-bayan, sobre el Corán 3:78 (n.º 7294) y 2:79 (n.º 1389)",
  ar_ref="تفسير الطبري، آل عمران ٧٨ والبقرة ٧٩", site=KSU, url="https://quran.ksu.edu.sa/tafseer/tabary/sura3-aya78.html · https://quran.ksu.edu.sa/tafseer/tabary/sura2-aya79.html",
  es=["7294 - Me contó Muhammad ibn Saʿd: me contó mi padre: me contó mi tío: me contó mi padre, de su padre, [[k:de Ibn Abbas, sobre Su dicho]]: «y entre ellos hay un grupo que tuerce sus lenguas con el Libro para que creáis que es del Libro»: son los judíos; [[k:añadían al libro de Dios lo que Dios no había revelado]].",
      "1389 - Nos contó Abu Kurayb: nos contó ʿUthman ibn Saʿid: nos contó Bishr ibn ʿUmara, de Abu Rawq, de al-Dahhak, [[k:de Ibn Abbas, que dijo]]: «Los ummiyyun [iletrados] son gente que no creyó en un mensajero que Dios envió ni en un libro que Dios reveló; [[k:y escribieron un libro con sus manos]] y luego dijeron a gente baja e ignorante: esto es de Dios, ‹para comprar con ello un precio vil›». Dijo: un bien mundano."],
  prueba="En al-Tabari, lo que figura como de Ibn Abbas sobre 3:78 y 2:79 es de cambio o adición al libro, no de interpretación. Y el taʿliq «yuharrifun: yuzilun… ni uno quita una palabra» no está en al-Tabari con cadena (Y7: 0 coincidencias en su tafsir de 2:75 a 5:41).",
  ojo="Las cadenas son de las discutidas: la 7294 es la de la familia de al-ʿAwfi; la 1389 pasa por al-Dahhak y Bishr ibn ʿUmara. No he evaluado a sus transmisores. Que la lectura de Ibn Abbas aparezca en varias formas es justo lo que cabe esperar de un material atribuido a él por muchas rutas: no basta con elegir la que conviene.", uso=USO),

 dict(id="TA12", key="Al2", tag="1270 H · al-Alusi (4:46)", specs=["TA-al446"],
  title="al-Alusi, 4:46: lo «transmitido de los antepasados, como Ibn Abbas», y la narración de Ibn Abbas en al-Bujari «cambiaron el Libro de Dios y escribieron con sus manos»",
  ref="al-Alusi, Ruh al-maʿani, sobre el Corán 4:46",
  ar_ref="روح المعاني، النساء ٤٦", site=QT, url="https://quran-tafsir.net/alusy/sura4-aya46.html",
  es=["[…] Y lo primero [que lo tergiversado es lo que está en la Torá] es lo transmitido de los antepasados, [[k:como Ibn Abbas y Mujahid y otros]]. Y su tergiversación es [[a:o bien quitarlo de los lugares donde Dios lo puso en la Torá, como cambiaron «de estatura media» en la descripción del Profeta y pusieron «alto» en su lugar, y como cambiaron la lapidación]] y pusieron la pena en su lugar, [[a:o bien desviarlo del significado que Dios reveló hacia lo que no es cierto con interpretaciones corruptas]] y retorcimientos desviados, como hacen los innovadores con los versículos del Corán que contradicen su doctrina. [[k:Y apoya lo primero lo que transmitió al-Bujari de Ibn Abbas, que dijo: «¿Cómo preguntáis a la gente del Libro…? Y Dios os ha dicho que la gente del Libro cambió el Libro de Dios y lo alteró, y escribieron con sus manos el Libro»]]…"],
  prueba="En 4:46 al-Alusi distingue dos formas de tergiversación —quitar el texto de su sitio, o desviar el sentido— y dice que lo primero se apoya en lo que al-Bujari transmite de Ibn Abbas («cambiaron el Libro de Dios… escribieron con sus manos»). Es el mismo autor que en 2:75 (TA03) dice que Ibn Abbas se inclinó por la interpretación.",
  ojo="No usar a al-Alusi como si Ibn Abbas sostuviera solo una cosa: en un autor y en dos versículos aparece con las dos. Lo que sí es de al-Alusi es el esquema de las dos formas. Texto en línea sin paginación impresa.", uso=USO),

 dict(id="TA13", key="Qa2", tag="1332 H · al-Qasimi (2:75)", specs=["TA-qs275"],
  title="al-Qasimi, 2:75: la lectura «de interpretación» es la más adecuada al sentido, pero «no se piense que con eso se descarta su tergiversación del texto: esa ocurrió sin duda»",
  ref="al-Qasimi, Mahasin al-taʾwil, sobre el Corán 2:75, «Advertencia»",
  ar_ref="محاسن التأويل، البقرة ٧٥", site=QT, url="https://quran-tafsir.net/qasimi/sura2-aya75.html",
  es=["(Advertencia): lo que citamos de Ibn Yarir [al-Tabari] y de Ibn Kathir al comentar «luego lo tergiversan» es lo más adecuado al contexto del versículo, [[a:y no se debe pensar que con eso se descarta su tergiversación del texto de la Torá, pues esta es cierta sin duda: cambiaron una parte de ella y alteraron su texto]], [[k:e interpretaron otra parte con un sentido distinto del que se quiso]]; y lo mismo se dice del Evangelio."],
  prueba="al-Qasimi, el más pro-fiabilidad de los reformistas, matiza que su preferencia por la lectura «interpretación» en 2:75 no excluye el cambio textual, que da por «cierto sin duda». Es la postura intermedia que Ibn al-Qayyim e Ibn Taymiyya describen (TA06).",
  ojo="Quien cite a al-Qasimi como apoyo de «solo interpretación» tiene que citar también esta nota: él no sostiene que no hubiera cambio de texto.", uso=USO),

 # ---------- E. Hallazgos de la segunda pasada (escaneo de 55 tafsires × 6 versículos) ----------
 dict(id="TA14", key="Hay2", tag="745 H · Abu Hayyan (5:13)", specs=["TA-hy513"],
  title="Abu Hayyan, 5:13: «lo dio como significado Ibn Abbas y otros, y dijeron: la tergiversación es por interpretación, no por cambio de palabras; no tienen capacidad para cambiarlas y no es posible»",
  ref="Abu Hayyan al-Andalusi, al-Bahr al-Muhit, sobre el Corán 5:13 («tergiversan las palabras de su lugar»)",
  ar_ref="البحر المحيط، المائدة ١٣", site=QT, url="https://quran-tafsir.net/hayyan/sura5-aya13.html",
  es=["«{Tergiversan las palabras de su lugar}»: es decir, cambian lo que les resultaba gravoso de sus normas, [[a:como el versículo de la lapidación, que sustituyeron, para sus jefes, por el ennegrecimiento: teñir la cara con carbón]]. [[k:Dio ese significado Ibn Abbas y otros,]] [[k:y dijeron: la tergiversación es por interpretación, no por cambiar las palabras; no tienen capacidad para cambiarlas y no es posible.]] ¿No ves que pusieron sus manos sobre el versículo de la lapidación? Y dijo Muqatil: su tergiversación de las palabras es que cambiaron la descripción del Mensajero —la quitaron y escribieron en su lugar otra—, [[a:y así cambiaron el significado y las palabras]]. [[a:Y lo correcto es que la tergiversación de las palabras de su lugar es el cambio en el texto y en el significado]], y quien haya examinado la Torá lo sabe con certeza; y ya se habló de este asunto."],
  prueba="Abu Hayyan (m. 745 H) vuelve a atribuir a Ibn Abbas la lectura «por interpretación» en un segundo pasaje, 5:13, y añade el argumento que la acompaña: «no tienen capacidad para cambiarlas y no es posible» (con el ejemplo de la mano sobre el versículo de la lapidación). Con 2:75 (TA01), son dos pasajes del mismo autor.",
  ojo="Cierra con su propio veredicto, en contra: «lo correcto es que la tergiversación es cambio en el texto y en el significado, y quien haya examinado la Torá lo sabe con certeza». Y su primer ejemplo (lapidación → ennegrecimiento) es un cambio de norma. La frase «y dijeron» es de Abu Hayyan: dice que la dieron «Ibn Abbas y otros», sin decir que esas palabras exactas sean de Ibn Abbas. Texto en línea, sin paginación impresa.", uso=USO),

 dict(id="TA15", key="Tha", tag="875 H · al-Thaʿalibi · copia de Ibn ʿAtiyya", specs=["TA-th275"], secondary=True,
  title="al-Thaʿalibi, 2:75: «Ibn Abbas sostuvo que su tergiversación y su cambio son solo por interpretación, y que el texto de la Torá permanece»; otro grupo dijo que cambiaron palabras",
  ref="al-Thaʿalibi, al-Yawahir al-hisan fi tafsir al-Qurʾan, sobre el Corán 2:75",
  ar_ref="الجواهر الحسان، البقرة ٧٥", site=QT, url="https://quran-tafsir.net/thaaliby/sura2-aya75.html",
  es=["[…] y tergiversar una cosa es inclinarla de un estado a otro. [[k:Y sostuvo Ibn Abbas que su tergiversación y su cambio son solo por interpretación, y que el texto de la Torá permanece;]] [[a:y sostuvo un grupo de sabios que cambiaron palabras por su cuenta, y que eso es posible en la Torá porque se les encomendó su custodia, e imposible en el Corán porque Dios garantizó su protección.]] Dije [yo, el autor]: y de Ibn Ishaq [se transmite] que por «el grupo» aquí se entiende una parte de los setenta que oyeron la palabra de Dios con Moisés. Fin de [la cita de] «Mujtasar al-Tabari»; y esto necesita una cadena sana."],
  prueba="al-Thaʿalibi (m. 875 H, Argel) dice casi con las mismas palabras que Ibn ʿAtiyya (H02a/H15) que Ibn Abbas sostuvo que la tergiversación fue solo por interpretación, quedando el texto de la Torá. Muestra que esa atribución se copió en el Magreb en el siglo XV.",
  ojo="No es un testimonio independiente: según la ficha del propio sitio, su tafsir es un compendio del de Ibn ʿAtiyya, y esta frase repite la de aquél. Aquí pone, junto a la de Ibn Abbas, la opinión de «un grupo de sabios»: cambiaron palabras, posible en la Torá (se les encomendó) pero no en el Corán (Dios lo protege): es el argumento clásico contra la fiabilidad. La cita final de Ibn Ishaq la da «de Mujtasar al-Tabari»; no he visto ese libro. Texto en línea, sin paginación impresa.", uso=USO),

 dict(id="TA16", key="Sid", tag="1307 H · Siddiq Hasan Khan · copia de Ibn Jaldun e Ibn al-Qayyim", specs=["TA-sd513", "TA-sd446"], secondary=True,
  title="Siddiq Hasan Khan: copia a Ibn Jaldun («Ibn Abbas, según lo que transmite de él al-Bujari, dijo que eso es improbable… lo tergiversaron con la interpretación») y a Ibn al-Qayyim",
  ref="Siddiq Hasan Khan al-Qannuyi, Fath al-bayan fi maqasid al-Qurʾan, sobre el Corán 5:13 y 4:46",
  ar_ref="فتح البيان في مقاصد القرآن، المائدة ١٣ والنساء ٤٦", site=QT, url="https://quran-tafsir.net/seddiq/sura5-aya13.html · https://quran-tafsir.net/seddiq/sura4-aya46.html",
  es=["[…] es decir, la sustituyen por otra o la interpretan en un sentido que no es el suyo; y se dijo: la quitan y la desvían; [[a:dijo Ibn Abbas: se refiere a los límites [hudud] de Dios.]] Dijo ʿAbd al-Rahman ibn Jaldun en Kitab al-ʿIbar: y en cuanto a lo que se dice de que sus sabios cambiaron los lugares de la Torá según sus propósitos en su religión, [[k:dijo Ibn Abbas, según lo que de él transmitió al-Bujari en su Sahih, que eso es improbable,]] y dijo: [[k:«¡Dios no lo quiera, que una nación se proponga cambiar su libro, revelado a su profeta, y lo cambie!»]] o algo en ese sentido. Dijo: [[k:y solo lo cambiaron y tergiversaron por interpretación,]] y lo atestigua Su dicho {y tienen la Torá, en la que está el juicio de Dios}: si hubieran cambiado las palabras de la Torá, no tendrían la Torá que contiene el juicio de Dios; y lo que viene en el Corán sobre atribuirles tergiversación y cambio, su significado es la interpretación, [[a:salvo que entre en las palabras algún cambio por descuido y falta de precisión,]] y la corrupción de quien no sabe escribir bien al copiarla: eso es posible por costumbre, sobre todo habiéndoseles ido el reino, dispersa su comunidad por los horizontes, iguales el cuidadoso y el descuidado, el sabio y el ignorante, y sin un freno que se lo guardara […]; así, por ello, entró en las hojas de la Torá, por lo general, [[a:un cambio y una tergiversación no deliberados de sus sabios y rabinos,]] y con todo eso se puede llegar a conocer lo correcto de ella […]",
      "[…] {y se dijo: aclara Su dicho «los que recibieron una parte del Libro»}: y «tahrif» es inclinar y quitar, es decir, lo inclinan y lo quitan de su lugar y ponen otra cosa en su sitio; o se refiere a que lo interpretan en un sentido que no es el suyo, [[k:y a eso se inclinó un grupo de los juristas y de los tradicionistas.]] [[a:Y dijo Ibn Abbas: tergiversan los límites de Dios en la Torá, y dijo Mujahid: es el cambio de la Torá por los judíos,]] y Dios los censuró por ello porque lo hacen por obstinación y rebeldía y por preferir los bienes de este mundo. Dijo el hafiz Ibn al-Qayyim —Dios tenga misericordia de él— en Ighathat al-lahfan: se ha discrepado sobre la Torá que tienen en sus manos: ¿está cambiada o el cambio se dio en la interpretación y no en lo revelado? [Hay] tres opiniones: [[a:dijo un grupo: toda o la mayoría está cambiada,]] y algunos se excedieron hasta decir que se puede usar para limpiarse tras orinar; y dijo un grupo de los imanes del hadiz, del fiqh y del kalam: [[k:solo ocurrió el cambio en la interpretación. Dijo al-Bujari en su Sahih: «yuharrifun: yuzilun, y nadie quita una palabra de un libro de Dios, pero lo interpretan en un sentido que no es el suyo»; y es también la opción de al-Razi.]] Y oí a nuestro maestro decir: ocurrió una disputa…"],
  prueba="Siddiq Hasan Khan (m. 1307 H, Bhopal, India) reproduce en 5:13 el pasaje entero de Ibn Jaldun (que atribuye a Ibn Abbas, vía al-Bujari, la lectura «por interpretación»), y en 4:46 el de Ibn al-Qayyim, con el taʿliq literal. Son atribuciones de segunda mano, pero prueban que en el siglo XIX seguían circulando como doctrina reconocida, incluso en el mundo musulmán de la India.",
  ojo="No es independiente: copia a Ibn Jaldun (H20a, H20b) y a Ibn al-Qayyim (TA06). Y en los dos versículos pone antes otra frase de Ibn Abbas: «se refiere a los límites [hudud] de Dios [en la Torá]» (azul), que es la de al-Tabari 11586 (TA18) y no dice si es de texto o de interpretación. Ibn Jaldun mismo admite una puerta en azul: cambio no deliberado, por descuido al copiar. Ibn al-Qayyim, en lo que sigue, sostiene la postura media (TA17).", uso=USO),

 dict(id="TA17", key="IQ2", tag="751 H · Ibn al-Qayyim · argumentos de esa postura", specs=["TA-ig2"],
  title="Ibn al-Qayyim recoge los argumentos de quienes dicen que el texto no se cambió: miles de copias dispersas, el versículo de la lapidación… y luego elige la postura media: «se añadió algo»",
  ref="Ibn al-Qayyim, Ighathat al-lahfan min masayid al-shaytan, capítulo 13 (Wikisource, cap. 34), continuación de TA06",
  ar_ref="إغاثة اللهفان، الباب الثالث عشر", site="ar.wikisource.org (texto)", url="https://ar.wikisource.org/wiki/إغاثة_اللهفان/الباب_الثالث_عشر/34",
  es=["Y de los argumentos de estos [los que dicen que el cambio fue solo de interpretación]: [[k:que la Torá se extendió por oriente y occidente de la tierra,]] y se difundió hacia el sur y el norte, y nadie sabe el número de sus copias sino Dios Altísimo, [[k:y es imposible que se pusieran de acuerdo en cambiar y alterar todas esas copias,]] de modo que no quede en la tierra una copia que no esté cambiada y alterada, y con la alteración por un solo método; [[k:y esto es algo que la razón excluye]] y atestigua su falsedad.",
      "Dijeron: y [los judíos] han coincidido en abandonar el precepto de la lapidación y no pudieron cambiarlo en la Torá; por eso, cuando la leyeron ante el Profeta ﷺ, el lector puso su mano sobre el versículo de la lapidación, y ʿAbd Allah ibn Salam le dijo: «levanta tu mano del versículo de la lapidación»; la levantó, y he aquí que brillaba debajo. [[k:Si hubieran cambiado las palabras de la Torá, esto habría sido de lo más importante que cambiarían.]]",
      "Y una tercera facción tomó el término medio y dijo: [[a:se le añadió y se cambiaron palabras leves,]] pero la mayor parte permanece como fue revelada y la alteración es en muy poco de ella; y entre quienes eligieron esta opinión está nuestro maestro [Ibn Taymiyya] en su libro al-Yawab al-sahih. Dijo: y esto, como en la Torá que tienen: que Dios, Glorificado y Altísimo, dijo a Abraham: «sacrifica a tu hijo, tu primogénito y único, Isaac»; [[a:así que «Isaac» es una adición suya en el texto de la Torá.]] Dije [Ibn al-Qayyim]: y es falsa con certeza, por diez razones…"],
  prueba="Ibn al-Qayyim (m. 751 H) expone, sin ridiculizarlos, los argumentos de la escuela «solo interpretación» que atribuye a al-Bujari: la dispersión de copias que hace imposible un cambio uniforme, el episodio de la mano sobre el versículo de la lapidación y la lógica de que, de haber cambiado el texto, lo primero que cambiarían sería eso. Son argumentos clásicos, hechos por sabios musulmanes, a favor de la integridad del texto.",
  ojo="Es de doble filo: él no los adopta. Expone la postura media (la suya y la de Ibn Taymiyya): «se añadió algo y se cambiaron algunas palabras leves», con el ejemplo de «Isaac» en Génesis 22 como adición, que califica de «falsa con certeza». Y estos argumentos son «de esos», no de Ibn Abbas. Presentarlos sin decir que Ibn al-Qayyim concluye otra cosa sería falsear.", uso=USO),

 dict(id="TA18", key="Tab3", tag="Ibn Abbas «hudud Allah» · al-Tabari 5:13 y Abu Hayyan 5:41", specs=["TA-tb513", "TA-hy541"],
  title="Lo que consta de Ibn Abbas sobre 5:13 y 5:41: «tergiversan» = «los límites [hudud] de Dios en la Torá»; Abu Hayyan lo explica: «cambiaron la lapidación: pusieron el azote en su lugar»",
  ref="al-Tabari, Yamiʿ al-bayan, sobre el Corán 5:13 (n.º 11586); Abu Hayyan, al-Bahr al-Muhit, sobre el Corán 5:41",
  ar_ref="تفسير الطبري، المائدة ١٣ · البحر المحيط، المائدة ٤١", site=KSU + " · " + QT, url="https://quran.ksu.edu.sa/tafseer/tabary/sura5-aya13.html · https://quran-tafsir.net/hayyan/sura5-aya41.html",
  es=["11586 - Me contó al-Muthanna, dijo: nos contó ʿAbd Allah, dijo: me contó Muʿawiya, de ʿAli [ibn Abi Talha], [[k:de Ibn Abbas, sobre Su dicho]] «tergiversan las palabras de su lugar»: [[k:significa: los límites [hudud] de Dios en la Torá;]] y dicen: «si Muhammad os ordena lo que vosotros hacéis, aceptadlo; y si os contradice, guardaos».",
      "{Tergiversan las palabras de [algunos de] sus lugares}: se leyó «al-kilm» [con otra vocalización], es decir: los quitan y los desvían de los lugares donde Dios los puso. [[k:Dijo Ibn Abbas y la mayoría: son los límites [hudud] de Dios en la Torá, y eso es que cambiaron la lapidación, es decir, pusieron el azote en lugar de la lapidación.]] Y dijo al-Hasan: cambian lo que oyen del Mensajero —la paz sea con él— mintiendo sobre él. Y se dijo: ocultando la descripción del Mensajero. Y se dijo: anulando la pena de talión una vez merecida. [[a:Y se dijo: por mala interpretación.]] Dijo al-Tabari: el sentido es «tergiversan el juicio de la palabra», y se omitió [«el juicio»] por ser sabido."],
  prueba="Es la narración de Ibn Abbas sobre 5:13 que al-Tabari consigna (y que Siddiq Hasan Khan repite: TA16). No dice «cambiaron palabras» ni «solo interpretaron»: dice que lo tergiversado son los hudud —las normas penales— de la Torá. En 5:41 Abu Hayyan atribuye a «Ibn Abbas y la mayoría» ese mismo dicho y lo explica con el caso de la lapidación («pusieron el azote en lugar de la lapidación»): lo que se tergiversa es la aplicación de la norma. Es compatible con una tergiversación de la práctica, no solo del texto; y el ejemplo no menciona ninguna palabra borrada de la Torá.",
  ojo="Es ambigua: «hudud Allah en la Torá» se puede leer como las normas cambiadas en la práctica (ennegrecimiento en lugar de lapidación) o como un cambio del texto que las contiene; el relato no lo precisa; «pusieron el azote en lugar de la lapidación» puede entenderse como cambio de práctica o de texto. No sirve de prueba de ninguna de las dos lecturas sin decirlo. Abu Hayyan en esa misma página da también «por mala interpretación» como una opinión más (azul). La cadena es la conocida de «ʿAli ibn Abi Talha» (vía Muʿawiya ibn Salih), que los críticos discuten; no la he evaluado.", uso=USO),

 dict(id="TA19", key="Raz", tag="606 H · al-Razi (2:75 y 3:78) · en contra", specs=["TA-rz275", "TA-rz378"],
  title="al-Razi: en 2:75 el Qadi dice que lo preferible es entenderlo como cambio de texto, «como se transmitió de Ibn Abbas: que añadieron y quitaron»; y en 3:78 da otro relato de Ibn Abbas: «escribieron un libro»",
  ref="al-Razi, Mafatih al-gayb (al-Tafsir al-kabir), sobre el Corán 2:75 y 3:78",
  ar_ref="مفاتيح الغيب، البقرة ٧٥ وآل عمران ٧٨", site=QT, url="https://quran-tafsir.net/alrazy/sura2-aya75.html · https://quran-tafsir.net/alrazy/sura3-aya78.html",
  es=["Cuestión segunda: dijo el Qadi: el tergiversar o es en la palabra o en el significado, y [[a:entender la tergiversación como cambio de la palabra es preferible a entenderla como cambio del significado,]] porque si la palabra de Dios, el Altísimo, se puede entender así, [[k:como se transmitió de Ibn Abbas, que añadieron en ella y quitaron,]] eso es preferible; y si no es posible, [[k:entonces hay que entenderlo como cambio de su interpretación, aunque la revelación quede firme;]] [[a:y eso solo es imposible cuando la palabra de Dios se ha hecho patente de modo masivamente transmitido, como la patencia del Corán;]] [[a:y antes de ser así, no es imposible la tergiversación de la propia palabra,]] aunque eso hay que examinarlo: si su cambio de ella afecta a que se sostenga la prueba con ella […]",
      "[…] Su dicho, el Altísimo, {tuercen sus lenguas}: y esta interpretación es de extrema belleza. Lo segundo: [[k:se transmitió de Ibn Abbas, que dijo: «los del grupo a quienes Dios no hablará el Día de la Resurrección ni mirará escribieron un libro]] [[k:en el que enredaron la descripción de Muhammad —la paz sea con él—, y la mezclaron con el libro en que estaba la descripción de Muhammad]], y luego dijeron: {esto viene de Dios}»."],
  prueba="Para ser honesto con Ibn Abbas: al-Razi, en 2:75, recoge del Qadi que lo preferible es entender «tergiversar» como cambio de la palabra, y lo apoya en lo «transmitido de Ibn Abbas: que añadieron y quitaron». Solo si eso no es posible habría que irse a la interpretación. En 3:78 da otro relato de Ibn Abbas: escribieron un libro que mezclaron con el que contenía la descripción de Muhammad.",
  ojo="Es el mismo al-Razi que Ibn al-Qayyim cita como partidario de «solo interpretación» (TA06). En 2:75 recoge la opinión del Qadi (en al-Razi suele designar a ʿAbd al-Yabbar; no lo he comprobado en este pasaje) y no la rechaza. Su condición («solo es imposible el cambio cuando la palabra se ha hecho masivamente transmitida, como el Corán; antes de eso no es imposible») es un criterio general: un libro no transmitido masivamente podría haberse alterado; no he visto que la aplique expresamente a la Biblia en este pasaje. En 5:13, en cambio, dice que en un libro transmitido masivamente no es posible cambiar las palabras (H16). Ambas citas son de Ibn Abbas en dirección de cambio o adición, no de interpretación. Texto en línea, sin paginación impresa.", uso=USO),
]
